"use client";

import { useState } from "react";
import { Field, inputClass } from "@/components/form";
import { NUEVO_CATALOGO } from "./catalogo-nuevo";

/**
 * A select of an open catalog (colors, categories) with a last option "+ Crear … nuevo…" that
 * reveals a text input. The server action creates the item first; its code is generated by the API.
 */
export function CatalogoSelect({
  id,
  name,
  label,
  createLabel,
  newNameLabel,
  options,
  emptyLabel,
  required = false,
  hint,
  defaultValue = "",
}: {
  id: string;
  name: string;
  label: string;
  /** Text of the last option, e.g. "+ Crear color nuevo…". */
  createLabel: string;
  /** Label of the revealed input, e.g. "Nombre del color nuevo". */
  newNameLabel: string;
  options: string[];
  /** Text of the empty option ("Sin color", "Elegir…"). */
  emptyLabel: string;
  required?: boolean;
  hint?: string;
  /** Option selected when the form opens (e.g. the color the product already has). */
  defaultValue?: string;
}) {
  const [value, setValue] = useState(defaultValue);
  const creating = value === NUEVO_CATALOGO;
  const newId = `${id}-nuevo`;
  return (
    <Field id={id} label={label} hint={hint}>
      <select
        id={id}
        name={name}
        required={required}
        value={value}
        onChange={(event) => setValue(event.target.value)}
        aria-describedby={hint ? `${id}-hint` : undefined}
        className={inputClass}
      >
        <option value="" disabled={required}>
          {emptyLabel}
        </option>
        {options.map((option) => (
          <option key={option} value={option}>
            {option}
          </option>
        ))}
        <option value={NUEVO_CATALOGO}>{createLabel}</option>
      </select>
      {creating ? (
        <div className="mt-3">
          <label htmlFor={newId} className="sr-only">
            {newNameLabel}
          </label>
          <input
            id={newId}
            name={`${name}_nuevo`}
            required
            maxLength={120}
            autoComplete="off"
            placeholder={newNameLabel}
            aria-describedby={`${newId}-hint`}
            className={inputClass}
          />
          <p
            id={`${newId}-hint`}
            className="mt-1 text-sm text-muted sm:text-xs"
          >
            El código se genera automáticamente al crearlo.
          </p>
        </div>
      ) : null}
    </Field>
  );
}
